-- Wrap auth.uid()/current_setting() in RLS policy predicates in (select ...) so
-- Postgres evaluates each once per statement (an InitPlan) instead of once per row --
-- the Supabase-documented RLS perf pattern. Covers USING and WITH CHECK. Predicate-
-- equivalent (row visibility unchanged). Generated by 'pgrls fix --rule PERF001'
-- (pgrls 0.44.0) and verified on Postgres 16 (PERF001 -> 0).

-- [PERF001] Wrap auth function call(s) in policy 'Can only view own subs data.' on public.subscriptions so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Can only view own subs data." ON public.subscriptions
    USING ((SELECT auth.uid()) = user_id);

-- [PERF001] Wrap auth function call(s) in policy 'Can update own user data.' on public.users so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Can update own user data." ON public.users
    USING ((SELECT auth.uid()) = id);

-- [PERF001] Wrap auth function call(s) in policy 'Can view own user data.' on public.users so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Can view own user data." ON public.users
    USING ((SELECT auth.uid()) = id);
